alter table public.comun_archive_items drop constraint comun_archive_items_item_type_check;
alter table public.comun_archive_items add constraint comun_archive_items_item_type_check check(item_type in('photograph','document','place','artist','music_release','oral_history','video','poster','newspaper','territorial_artwork','community_radio_program','community_radio_episode','community_radio_clip','other'));
alter table public.comun_archive_assets drop constraint comun_archive_assets_asset_role_check;
alter table public.comun_archive_assets add constraint comun_archive_assets_asset_role_check check(asset_role in('original','public_version','thumbnail','cover','transcript','attachment','artwork_private_original','artwork_public_detail','artwork_public_card','artwork_public_thumbnail','artwork_public_social_preview','artwork_rights_document','artwork_context_document','artwork_process_photo','radio_private_original','radio_public_episode','radio_public_preview','radio_waveform','radio_transcript_document','radio_voice_consent_document','radio_music_rights_document','radio_cover_derivative','radio_context_document'));
update public.comun_pauta_modules set module_type='community_radio' where module_type='community_radio_future';
alter table public.comun_pauta_modules drop constraint comun_pauta_modules_module_type_check;
alter table public.comun_pauta_modules add constraint comun_pauta_modules_module_type_check check(module_type in('overview','construction_circle','reports','evidence','map','observatory','metrics','documents','timeline','proposals','actions','tasks','calendar','results','archive','art_gallery','community_radio','participation'));
alter table public.comun_archive_processing_jobs drop constraint comun_archive_processing_jobs_job_type_check;
alter table public.comun_archive_processing_jobs add constraint comun_archive_processing_jobs_job_type_check check(job_type in('historical_photo_derivatives','music_external_link_check','territorial_artwork_derivatives','community_radio_audio'));
alter table public.comun_archive_processing_jobs drop constraint comun_archive_processing_job_target_check;
alter table public.comun_archive_processing_jobs add constraint comun_archive_processing_job_target_check check((job_type in('historical_photo_derivatives','territorial_artwork_derivatives','community_radio_audio') and archive_asset_id is not null)or(job_type='music_external_link_check'and external_link_id is not null));
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)values('radio-private-originals','radio-private-originals',false,262144000,array['audio/wav','audio/mpeg','audio/mp4','audio/ogg','audio/flac']),('radio-public-audio','radio-public-audio',true,262144000,array['audio/mpeg','application/json','text/vtt','text/plain'])on conflict(id)do update set public=excluded.public,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;

create table public.comun_radio_programs(archive_item_id uuid primary key references public.comun_archive_items(id)on delete cascade,title_public text not null,slug_public text not null unique,subtitle_public text,description_public text not null,format_type text not null check(format_type in('news','interview','debate','storytelling','music','cultural','educational','bulletin','documentary','children','mixed','other')),status text not null default'draft'check(status in('draft','review','active','paused','archived')),territory_id uuid references public.comun_hub_territories(id)on delete set null,pauta_id uuid references public.comun_pauta_spaces(id)on delete set null,cover_artwork_item_id uuid references public.comun_archive_items(id)on delete set null,frequency_public text,publication_status text not null default'draft'check(publication_status in('draft','review','published','unpublished','archived')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.comun_radio_episodes(archive_item_id uuid primary key references public.comun_archive_items(id)on delete cascade,program_item_id uuid not null references public.comun_archive_items(id)on delete restrict,season_number integer,episode_number integer,title_public text not null,slug_public text not null unique,summary_public text not null,description_public text,recorded_at date,published_at timestamptz,duration_seconds integer check(duration_seconds between 1 and 7200),territory_id uuid references public.comun_hub_territories(id)on delete set null,pauta_id uuid references public.comun_pauta_spaces(id)on delete set null,action_id uuid references public.comun_mobilization_actions(id)on delete set null,cover_artwork_item_id uuid references public.comun_archive_items(id)on delete set null,publication_status text not null default'draft'check(publication_status in('draft','audio_processing','rights_review','editorial_review','published','unpublished','withdrawn','archived')),sensitivity_level text not null default'normal'check(sensitivity_level in('normal','attention','restricted')),transcript_status text not null default'unavailable'check(transcript_status in('unavailable','pending','draft','review','published','withdrawn')),allow_download boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.comun_radio_credits(id uuid primary key default gen_random_uuid(),episode_item_id uuid not null references public.comun_archive_items(id)on delete cascade,agent_id uuid references public.comun_archive_agents(id)on delete restrict,credit_role text not null check(credit_role in('host','co_host','guest','interviewer','interviewee','reporter','producer','editor','sound_editor','researcher','writer','musician','composer','performer','collective','rights_holder','translator','transcriber','photographer','cover_artist','anonymous_participant')),public_credit text not null,position integer not null default 0,public_visibility text not null default'public'check(public_visibility in('public','private')),private_notes text,created_at timestamptz not null default now());
create table public.comun_radio_voice_consents(id uuid primary key default gen_random_uuid(),episode_item_id uuid not null references public.comun_archive_items(id)on delete cascade,agent_id uuid references public.comun_archive_agents(id)on delete set null,participant_reference_private text,consent_status text not null default'pending'check(consent_status in('pending','approved','partially_approved','rejected','expired','withdrawn')),allow_private_preservation boolean not null default false,allow_comun_audio boolean not null default false,allow_transcript boolean not null default false,allow_social_clips boolean not null default false,allow_print_quotes boolean not null default false,allow_campaign_use boolean not null default false,allow_educational_use boolean not null default false,allow_name_publication boolean not null default false,public_name_override text,valid_from date,valid_until date,withdrawal_requested_at timestamptz,withdrawal_completed_at timestamptz,evidence_asset_id uuid references public.comun_archive_assets(id)on delete set null,private_notes text,reviewed_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.comun_radio_music_uses(id uuid primary key default gen_random_uuid(),episode_item_id uuid not null references public.comun_archive_items(id)on delete cascade,recording_agent_id uuid references public.comun_archive_agents(id)on delete set null,composition_agent_id uuid references public.comun_archive_agents(id)on delete set null,title_public text not null,performer_public text,composer_public text,usage_type text not null check(usage_type in('full_track','excerpt','background','theme','incidental','live_performance','public_domain','original_commission','other')),start_seconds integer,end_seconds integer,rights_status text not null default'pending'check(rights_status in('pending','approved','rejected','expired','withdrawn','public_domain_verified')),allow_streaming boolean not null default false,allow_download boolean not null default false,allow_social_clip boolean not null default false,allow_campaign_use boolean not null default false,license_public text,evidence_asset_id uuid references public.comun_archive_assets(id)on delete set null,private_notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(end_seconds is null or start_seconds is null or end_seconds>start_seconds));
create table public.comun_radio_safety_reviews(episode_item_id uuid primary key references public.comun_archive_items(id)on delete cascade,minor_involved_private boolean not null default false,guardian_authorization_confirmed boolean not null default false,sensitive_location_private boolean not null default false,identifiable_people_private boolean not null default false,reinforced_review_status text not null default'not_required'check(reinforced_review_status in('not_required','pending','approved','rejected')),private_notes text,reviewed_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.comun_radio_transcript_versions(id uuid primary key default gen_random_uuid(),episode_item_id uuid not null references public.comun_archive_items(id)on delete cascade,version_number integer not null,transcript_type text not null check(transcript_type in('txt','vtt','manual_editorial')),content text not null,status text not null default'draft'check(status in('draft','review','published','withdrawn')),contains_redactions boolean not null default false,reviewed_at timestamptz,created_at timestamptz not null default now(),unique(episode_item_id,version_number));
create table public.comun_radio_episode_chapters(id uuid primary key default gen_random_uuid(),episode_item_id uuid not null references public.comun_archive_items(id)on delete cascade,start_seconds integer not null check(start_seconds>=0),end_seconds integer, title_public text not null,summary_public text,related_pauta_id uuid references public.comun_pauta_spaces(id)on delete set null,related_archive_item_id uuid references public.comun_archive_items(id)on delete set null,position integer not null default 0,created_at timestamptz not null default now(),check(end_seconds is null or end_seconds>start_seconds));
create table public.comun_radio_schedule_entries(id uuid primary key default gen_random_uuid(),program_item_id uuid not null references public.comun_archive_items(id)on delete cascade,episode_item_id uuid references public.comun_archive_items(id)on delete set null,title_public text not null,starts_at timestamptz not null,ends_at timestamptz not null,schedule_type text not null check(schedule_type in('premiere','replay','special','bulletin','live_future')),status text not null default'draft'check(status in('draft','published','cancelled','completed')),recurrence_public text,public_note text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(ends_at>starts_at));
create table public.comun_radio_contributions(id uuid primary key default gen_random_uuid(),member_user_id uuid,public_protocol text not null unique,contribution_type text not null check(contribution_type in('program_proposal','pauta_proposal','community_audio','authorized_testimony','own_music','agenda','correction','complement','withdrawal')),title_suggestion text not null,context_suggestion text not null,creator_credit_suggestion text,private_contact text,status text not null default'pending'check(status in('pending','information_requested','rights_review','editorial_review','processing','approved','rejected','published','withdrawn','archived')),information_request_public text,next_action_public text,internal_notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.comun_radio_editorial_versions(id uuid primary key default gen_random_uuid(),episode_item_id uuid not null references public.comun_archive_items(id)on delete cascade,version_number bigint not null,sanitized_snapshot jsonb not null,change_type text not null,created_by uuid,created_at timestamptz not null default now(),unique(episode_item_id,version_number));
do $$ declare t text; begin foreach t in array array['comun_radio_programs','comun_radio_episodes','comun_radio_credits','comun_radio_voice_consents','comun_radio_music_uses','comun_radio_safety_reviews','comun_radio_transcript_versions','comun_radio_episode_chapters','comun_radio_schedule_entries','comun_radio_contributions','comun_radio_editorial_versions'] loop execute format('alter table public.%I enable row level security',t); execute format('revoke all on public.%I from anon,authenticated',t); execute format('grant select,insert,update,delete on public.%I to service_role',t); end loop; end $$;
create index comun_radio_episodes_program_idx on public.comun_radio_episodes(program_item_id,publication_status,published_at desc);create index comun_radio_contributions_member_idx on public.comun_radio_contributions(member_user_id,created_at desc);create index comun_radio_schedule_public_idx on public.comun_radio_schedule_entries(status,starts_at);
create trigger comun_radio_programs_updated_at before update on public.comun_radio_programs for each row execute function public.set_updated_at();create trigger comun_radio_episodes_updated_at before update on public.comun_radio_episodes for each row execute function public.set_updated_at();create trigger comun_radio_voice_consents_updated_at before update on public.comun_radio_voice_consents for each row execute function public.set_updated_at();create trigger comun_radio_music_uses_updated_at before update on public.comun_radio_music_uses for each row execute function public.set_updated_at();create trigger comun_radio_safety_reviews_updated_at before update on public.comun_radio_safety_reviews for each row execute function public.set_updated_at();create trigger comun_radio_schedule_updated_at before update on public.comun_radio_schedule_entries for each row execute function public.set_updated_at();create trigger comun_radio_contributions_updated_at before update on public.comun_radio_contributions for each row execute function public.set_updated_at();
